import type { Metadata } from "next";

/** Generated by app/opengraph-image.tsx. Listed explicitly because a page's own
 * `openGraph` object replaces (rather than merges with) the parent's images. */
const socialImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: "Ibrahima Mamby Bah — MambyTech: Building Infrastructure. Engineering Solutions.",
};

/** Per-page metadata with a canonical URL and matching social metadata. */
export function pageMetadata({ title, description, path }: { title: string; description: string; path: string }): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      title,
      description,
      url: path,
      type: "website",
      siteName: "MambyTech",
      locale: "en_US",
      images: [socialImage],
    },
    twitter: { card: "summary_large_image", title, description, images: [socialImage] },
  };
}
